function C.Resolve(P,kind)
 local e=C.entries[kind]
 if not e then return nil,'UNSUPPORTED_TYPE' end
 local w=P.Info('GreatWorks',kind)
 if not w or w.GreatWorkObjectType~=e[1] then return nil,'CATEGORY_METADATA' end
 local era=w.EraType;local source='WORK_ERA'
 if era==nil then
  local gp=e[4]~='' and w.GreatPersonIndividualType==e[2] and P.Info('GreatPersonIndividuals',e[2])
  if not gp or gp.EraType~=e[4] or e[1]=='GREATWORKOBJECT_ARTIFACT' then return nil,'ERA_UNAVAILABLE' end
  era=e[4];source='VERIFIED_NATIVE_CREATOR'
 elseif era~=e[3] then return nil,'UNREVIEWED_ERA' end
 if not P.Info('Eras',era) then return nil,'ERA_UNAVAILABLE' end
 return {type=kind,category=e[1],era=era,name=w.Name,eraSource=source,provenance=e[5]}
end
function C.Build(P)
 local out={version=C.version,works={},eras={},complete=true,count=0,excluded={}}
 for kind in pairs(C.entries) do
  if P.Info('GreatWorks',kind) then
   local w,why=C.Resolve(P,kind)
   if w then out.works[kind]=w;out.eras[w.era]=true;out.count=out.count+1
   else out.excluded[kind]=why;out.complete=false end
  end
 end
 return out
end
